<?php require 'config/database.php';require 'helpers/functions.php';login_required();if($_SERVER['REQUEST_METHOD']==='POST'){check_token();admin_required();$n=trim($_POST['name']??'');$d=trim($_POST['description']??'');if($n!==''){try{$s=$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$s->execute([$n,$d?:null]);msg('Kategori ditambahkan.');}catch(PDOException $e){msg('Nama kategori sudah ada.','error');}}else msg('Nama kategori wajib.','error');go('categories.php');}$rows=$pdo->query('SELECT c.name,c.description,COUNT(p.id) total FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();header_html('Kategori');if($_SESSION['user']['role']==='admin')echo '<section><form method="post"><input type="hidden" name="csrf" value="'.e(token()).'"><label>Nama kategori</label><input name="name" required><label>Deskripsi</label><input name="description"><button>Tambah</button></form></section>';echo '<section><table><tr><th>Nama</th><th>Deskripsi</th><th>Produk</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['description']).'</td><td>'.e($r['total']).'</td></tr>';echo '</table></section>';footer_html();